const out = [];
const log = (...a) => out.push(a.map((x) => typeof x === "bigint" ? x + "n" : typeof x === "string" ? JSON.stringify(x) : JSON.stringify(x)).join(" "));
const t = (name, fn) => { try { log(name, fn()); } catch (e) { log(name, "THROWS", e.constructor.name, e.code ?? ""); } };
const s = "héllo wörld ✓ 😀";
for (const enc of ["utf8", "hex", "base64", "base64url", "latin1", "ascii", "ucs2", "utf16le", "binary"]) {
  t("enc " + enc, () => { const b = Buffer.from(s, enc); return [b.length, b.toString(enc), Array.from(b.subarray(0, 8))]; });
}
t("hex odd", () => Array.from(Buffer.from("abc", "hex")));
t("hex bad", () => Array.from(Buffer.from("zz11", "hex")));
t("b64 ws", () => Buffer.from(" aGVs bG8=\n", "base64").toString());
t("b64url", () => Buffer.from([251, 255, 254]).toString("base64url") + Buffer.from([251, 255, 254]).toString("base64"));
t("alloc fill", () => [Buffer.alloc(5, 1).toJSON().data, Buffer.alloc(5, "ab").toString(), Buffer.alloc(4, "6162", "hex").toString()]);
t("concat", () => Buffer.concat([Buffer.from("ab"), Buffer.from("cd")], 3).toString());
t("compare", () => [Buffer.compare(Buffer.from("a"), Buffer.from("b")), Buffer.from("b").compare(Buffer.from("a")), Buffer.from("a").equals(Buffer.from("a"))]);
t("indexOf", () => { const b = Buffer.from("this is a buffer buffer"); return [b.indexOf("buffer"), b.lastIndexOf("buffer"), b.indexOf("is", 3), b.indexOf(0x61), b.includes("nope"), b.indexOf(Buffer.from("is"), -10), b.indexOf("")]; });
t("slice shares", () => { const b = Buffer.from("abcdef"); const c = b.slice(1, 3); c[0] = 0x7a; return b.toString(); });
t("subarray shares", () => { const b = Buffer.from("abcdef"); b.subarray(2)[0] = 0x7a; return b.toString(); });
t("copy", () => { const a = Buffer.from("abcdef"); const b = Buffer.alloc(4); return [a.copy(b, 1, 2), b.toString("hex")]; });
t("copy overlap", () => { const a = Buffer.from("abcdef"); a.copy(a, 2, 0, 4); return a.toString(); });
t("write", () => { const b = Buffer.alloc(8); return [b.write("héy", 1), b.write("zz", 6, "latin1"), b.toString("hex")]; });
t("write trunc", () => { const b = Buffer.alloc(3); return [b.write("é✓"), b.toString("hex")]; });
t("fill", () => [Buffer.alloc(6).fill("abc").toString(), Buffer.alloc(6).fill("abc", 1, 5).toString("hex"), Buffer.alloc(4).fill(0x101).toString("hex")]);
const b = Buffer.alloc(16);
t("ints", () => { b.writeUInt32BE(0xdeadbeef, 0); b.writeInt16LE(-2, 4); b.writeUInt8(255, 6); b.writeDoubleBE(1.5, 8); return [b.toString("hex"), b.readUInt32LE(0), b.readInt32BE(0), b.readInt16BE(4), b.readUInt16LE(4), b.readInt8(6), b.readDoubleBE(8)]; });
t("uintbe", () => { const c = Buffer.alloc(6); c.writeUIntBE(0x123456789abc, 0, 6); return [c.toString("hex"), c.readUIntBE(0, 6), c.readUIntLE(0, 6), c.readIntBE(0, 6), c.readIntLE(0, 3)]; });
t("intbe neg", () => { const c = Buffer.alloc(3); c.writeIntBE(-5, 0, 3); return [c.toString("hex"), c.readIntBE(0, 3)]; });
t("bigint", () => { const c = Buffer.alloc(8); c.writeBigUInt64LE(0x0102030405060708n); return [c.toString("hex"), c.readBigUInt64BE(), c.readBigInt64LE()]; });
t("float", () => { const c = Buffer.alloc(4); c.writeFloatLE(3.14); return [c.readFloatLE(), c.readFloatBE()]; });
t("oob read", () => Buffer.alloc(2).readUInt32LE(0));
t("oob offset", () => Buffer.alloc(4).readUInt8(4));
t("oob write", () => Buffer.alloc(4).writeUInt8(300, 0));
t("badenc", () => Buffer.from("a", "nope"));
t("isEncoding", () => [Buffer.isEncoding("utf8"), Buffer.isEncoding("UCS2"), Buffer.isEncoding("x"), Buffer.isEncoding("")]);
t("byteLength", () => [Buffer.byteLength(s), Buffer.byteLength("aGVsbG8=", "base64"), Buffer.byteLength("abcd", "hex"), Buffer.byteLength(new ArrayBuffer(7))]);
t("from array", () => [Buffer.from([1, 2, 257, -1]).toJSON().data, Buffer.from({ type: "Buffer", data: [9, 8] }).toJSON().data, Buffer.from(new Uint16Array([1, 258])).toJSON().data]);
t("from ab", () => { const ab = new ArrayBuffer(4); const c = Buffer.from(ab, 1, 2); c[0] = 5; return [new Uint8Array(ab)[1], c.length]; });
t("swap", () => [Buffer.from("01020304", "hex").swap16().toString("hex"), Buffer.from("01020304", "hex").swap32().toString("hex")]);
t("json", () => JSON.stringify(Buffer.from("hi")));
t("toString range", () => [Buffer.from("abcdef").toString("utf8", 1, 4), Buffer.from("abcdef").toString("hex", 2)]);
t("isBuffer", () => [Buffer.isBuffer(Buffer.alloc(1)), Buffer.isBuffer(new Uint8Array(1)), Buffer.alloc(2) instanceof Uint8Array]);
t("iter", () => [...Buffer.from("ab").entries()]);
t("aliases", () => [typeof Buffer.alloc(4).readUint32LE, typeof Buffer.alloc(4).writeUint8]);
console.log(out.join("\n"));
